use std::collections::HashMap;

struct Log {
    entries: Vec<(String, Option<String>)>,
    index: HashMap<String, usize>,
}

impl Log {
    fn set(&mut self, k: &str, v: &str) {
        self.entries.push((k.to_string(), Some(v.to_string())));
        self.index.insert(k.to_string(), self.entries.len() - 1);
    }
    fn del(&mut self, k: &str) {
        self.entries.push((k.to_string(), None));
        self.index.insert(k.to_string(), self.entries.len() - 1);
    }
    fn get(&self, k: &str) -> Option<&str> {
        let pos = *self.index.get(k)?;
        self.entries[pos].1.as_deref()
    }
    fn compact(&mut self) {
        let mut entries = Vec::new();
        let mut index = HashMap::new();
        for (k, &pos) in &self.index {
            if let Some(v) = &self.entries[pos].1 {
                entries.push((k.clone(), Some(v.clone())));
                index.insert(k.clone(), entries.len() - 1);
            }
        }
        self.entries = entries;
        self.index = index;
    }
}

fn main() {
    let mut log = Log { entries: vec![], index: HashMap::new() };
    log.set("a", "1");
    log.set("b", "2");
    log.set("a", "3");
    log.del("b");
    println!("{:?} {:?} {}", log.get("a"), log.get("b"), log.entries.len());
    log.compact();
    println!("{:?} {}", log.get("a"), log.entries.len());
}

