    unsafe { qsort(ptrs.as_mut_ptr().cast(), ptrs.len(), size_of::<*const c_char>(), compare) };
    for p in ptrs {
        println!("{}", unsafe { CStr::from_ptr(p) }.to_str().unwrap());
    }
}

