const W: usize = 12;
const H: usize = 3;

struct Screen {
    cells: [u16; W * H],
    row: usize,
    col: usize,
    attr: u8,
}

impl Screen {
    fn newline(&mut self) {
        self.row += 1;
        self.col = 0;
    }

    fn write_byte(&mut self, b: u8) {
        if b == b'\n' {
            self.newline();
            return;
        }
        if self.col == W {
            self.newline();
        }
        self.cells[self.row * W + self.col] = (self.attr as u16) << 8 | b as u16;
        self.col += 1;
    }

    fn show(&self) {
        for r in 0..H {
            let line: String = self.cells[r * W..(r + 1) * W]
                .iter()
                .map(|&c| match (c & 0xff) as u8 {
                    0 => '.',
                    b if b < 0x20 => '?',
                    b => b as char,
                })
                .collect();
            println!("|{line}|");
        }
    }
}

fn main() {
    let mut s = Screen { cells: [0; W * H], row: 0, col: 0, attr: 0x0b };
    for &b in b"hello\nkernel world" {
        s.write_byte(b);
    }
    s.show();
    println!("attribute {:#04x}", s.cells[0] >> 8);
}
